function buildingsPanel(){showPanel(`<div class="row"><div><div class="eyebrow">A home worth returning to</div><h2>Rebuild Cinderfall</h2></div><button id="back">Back</button></div><p class="gold">◈ ${save.gold} gold · ${save.wood} wood · ${save.stone} stone · ${save.iron} iron</p><div class="grid">${BUILDINGS.map(b=>{let n=save.buildings[b.id],cost=Math.round(b.cost*Math.pow(1.65,n)),wood=b.wood*(n+1),stone=b.stone*(n+1),iron=n>=2?n-1:0,locked=b.id!=='guild'&&n>=2+save.buildings.guild*2,can=n<b.max&&!locked&&save.gold>=cost&&save.wood>=wood&&save.stone>=stone&&save.iron>=iron;return `<div class="card"><span class="glyph">${b.icon}</span><h3>${b.name}</h3><span class="pill">Level ${n} / ${b.max}</span><p>${b.text}</p><p class="gold">${n===b.max?'Fully rebuilt':`${cost} gold · ${wood} wood<br>${stone} stone${iron?' · '+iron+' iron':''}`}</p><button data-upgrade="${b.id}" ${can?'':'disabled'}>${n===b.max?'Complete':locked?'Upgrade Guild Hall':'Build upgrade'}</button></div>`;}).join('')}</div><p class="muted">All town upgrades are shared by your heroes. Guild Hall unlocks specializations and higher building tiers.</p>`);bind('back',townPanel);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{let v=BUILDINGS.find(x=>x.id===b.dataset.upgrade),n=save.buildings[v.id],cost=Math.round(v.cost*1.65**n);if(save.gold<cost)return;save.gold-=cost;save.wood-=v.wood*(n+1);save.stone-=v.stone*(n+1);if(n>=2)save.iron-=n-1;save.buildings[v.id]++;sound('level');persist();buildingsPanel();notify(v.name+' improved');});}
function inventoryPanel(fromTown=false){showPanel(`<div class="row"><div><div class="eyebrow">Permanent equipment</div><h2>Armory</h2></div><button id="back">${fromTown?'Back':'Resume'}</button></div><p>Equip one weapon, armor and charm. Equipment is kept after death. Equipped bonuses apply immediately.</p><div class="two"><div>${['weapon','armor','charm'].map(slot=>{let g=save.gear.find(x=>x.id===save.equipped[slot]);return `<div class="item-row"><div><span class="eyebrow">${slot}</span><h3>${g?g.name:'Travel-worn '+slot}</h3><p>${g?gearText(g):'No bonus'}</p></div></div>`;}).join('')}<div class="divider"></div><h3>Run trinkets</h3><p>${(run?.relics||[]).map(id=>RELICS.find(r=>r.id===id).name).join(' · ')||'None. Find reliquaries inside the dungeon.'}</p></div><div style="max-height:380px;overflow:auto">${save.gear.length?save.gear.slice().reverse().map(g=>`<div class="item-row"><div><strong class="${g.rarity}">${g.name}</strong><p>${g.slot} · ${gearText(g)}</p></div><button data-equip="${g.id}" ${save.equipped[g.slot]===g.id?'disabled':''}>${save.equipped[g.slot]===g.id?'Equipped':'Equip'}</button></div>`).join(''):'<p>No equipment yet. Open chests and defeat guardians.</p>'}</div></div>`);bind('back',()=>fromTown?townPanel():closePanel());document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{let g=save.gear.find(g=>g.id===b.dataset.equip);save.equipped[g.slot]=g.id;persist();inventoryPanel(fromTown);sound('coin');});}
