function createGear(quality=0){let slot=choice(['weapon','armor','charm']),tier=Math.min(5,Math.floor(run.floor/2)+quality+Math.floor(Math.random()*2)),rarity=tier>=4?'legendary':tier>=2?'epic':tier>=1?'rare':'common',stat=slot==='weapon'?'damage':slot==='armor'?'armor':choice(['hp','mana','crit']),value=stat==='damage'?4+tier*3:stat==='armor'?2+tier:stat==='crit'?.03+tier*.015:15+tier*8;let g={id:'g'+Date.now()+Math.random().toString(36).slice(2,6),slot,stat,value,name:GEAR_NAMES[slot][tier],rarity};save.gear.push(g);if(!save.equipped[slot])save.equipped[slot]=g.id;notify(`Equipment found: ${g.name} · ${gearText(g)}`);persist();return g;}
