function damagePlayer(amount,source){if(p.invuln>0||p.dashTime>0)return;let s=stats();amount=Math.max(1,Math.round(amount-s.armor));p.hp-=amount;p.invuln=.7;shake=6;floating(p.x,p.y-24,'−'+amount,'#ff827b');burst(p.x,p.y,'#cf5c56',10);sound('hurt');if(s.thorns)for(let e of entities)if(e.hp>0&&dist(e,p)<90)hit(e,s.thorns,10,true);if(p.hp<=0){if(s.revive&&!run.revived){run.revived=true;p.hp=s.hp*.5;p.invuln=3;circle(p.x,p.y,120,'#ffd690',1);notify('The Phoenix Feather burns. Rise again.');}else finishRun(false);}}
function projectile(x,y,angle,speed,damage,kind,enemy=false,options={}){shots.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,damage,kind,enemy,life:options.life||1.5,r:kind==='fire'?7:kind==='soul'?6:4,pierce:options.pierce||0,hit:[],...options});}
