function navigation(){field=Array.from({length:map.h},()=>Array(map.w).fill(9999));let sx=Math.floor(p.x/T),sy=Math.floor(p.y/T);if(!map.tiles[sy]?.[sx])return;let q=[[sx,sy]],i=0;field[sy][sx]=0;while(i<q.length){let [x,y]=q[i++];for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy;if(map.tiles[ny]?.[nx]&&field[ny][nx]>field[y][x]+1){field[ny][nx]=field[y][x]+1;q.push([nx,ny]);}}}}
function chase(e,dt,mult=1){let dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy);if(!lineClear(e,p)&&field){let x=Math.floor(e.x/T),y=Math.floor(e.y/T),best=field[y]?.[x]??9999,bx=x,by=y;for(let [ox,oy] of [[1,0],[-1,0],[0,1],[0,-1]]){if(field[y+oy]?.[x+ox]<best){best=field[y+oy][x+ox];bx=x+ox;by=y+oy;}}dx=(bx+.5)*T-e.x;dy=(by+.5)*T-e.y;d=Math.hypot(dx,dy);}if(d>3){let speed=e.speed*mult*(e.slow>0?.45:1);move(e,dx/d*speed*dt,dy/d*speed*dt,Math.min(11,e.r*.6));e.angle=Math.atan2(dy,dx);e.walk+=dt*speed/20;}}
