function updateHud(){if(!p||!run)return;let s=stats(),h=hero(),c=cls();$('#hud').innerHTML=`<div><strong>${c.name} · LV ${h.level}</strong><div class="bar"><i style="width:${100*p.hp/s.hp}%"></i></div><div>${Math.ceil(p.hp)} / ${Math.round(s.hp)} health</div><div class="bar mana"><i style="width:${100*p.mana/s.mana}%"></i></div><div class="bar xp"><i style="width:${100*h.xp/levelXp(h.level)}%"></i></div><div class="skills"><div class="skill ${p.q<=0?'ready':''}"><b>${p.q>0?p.q.toFixed(1):'Q'}</b>${c.q.split(' ')[0]}</div><div class="skill ${p.e<=0?'ready':''}"><b>${p.e>0?p.e.toFixed(1):'E'}</b>${c.e.split(' ')[0]}</div><div class="skill ${p.dash<=0?'ready':''}"><b>${p.dash>0?p.dash.toFixed(1):'SPC'}</b>Dodge</div><div class="skill"><b>R ×${p.potions}</b>Potion</div></div></div><div class="status-right"><strong>${bio().name.toUpperCase()}</strong><p style="margin:6px 0;color:#d4c0a0;font-size:12px">Depth ${run.floor+1} / 6 · ${run.kills} defeated</p>◈ ${run.gold}<br><small>${run.wood} wood · ${run.stone} stone · ${run.iron} iron</small><p class="muted" style="margin-top:8px">${run.relics.length} trinkets · ${Math.floor(run.seconds/60)}:${String(Math.floor(run.seconds%60)).padStart(2,'0')}</p></div>`;}
