function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,TAU);ctx.fill();}
function text(s,x,y,size=14,color='#e0d3b8',align='center'){ctx.font=`${size}px Inter, sans-serif`;ctx.textAlign=align;ctx.fillStyle='#060a0d';ctx.fillText(s,x+1,y+2);ctx.fillStyle=color;ctx.fillText(s,x,y);}
function tree(x,y,seed=0,autumn=false){let sway=Math.sin(time*1.3+seed)*1.5;ellipse(x,y+10,25,11,'#0005');rect(x-4,y-17,8,31,'#322b29');rect(x-2,y-17,3,26,'#65513a');if(autumn){for(let j=0;j<5;j++){let xx=x+Math.sin(seed+j*5)*14,yy=y-28-j*6;ellipse(xx,yy,19,14,['#784a32','#91623b','#aa7340','#bb8846','#8c653b'][j]);rect(xx-9,yy-5,8,3,'#d09b54');}}else{for(let k=0;k<3;k++){let yy=y-15-k*15,rr=26-k*4;ctx.fillStyle=['#1c352f','#294436','#36523d'][k];ctx.beginPath();ctx.moveTo(x+sway,yy-29);ctx.lineTo(x-rr,yy+12);ctx.lineTo(x+rr,yy+12);ctx.closePath();ctx.fill();ctx.fillStyle='#52704a';ctx.beginPath();ctx.moveTo(x+sway,yy-26);ctx.lineTo(x-rr+6,yy+7);ctx.lineTo(x-5,yy+2);ctx.closePath();ctx.fill();}}}
function ground(){let b=bio(),startX=Math.max(0,Math.floor(cam.x/T)-1),endX=Math.min(map.w,Math.ceil((cam.x+W)/T)+1),startY=Math.max(0,Math.floor(cam.y/T)-2),endY=Math.min(map.h,Math.ceil((cam.y+H)/T)+3);for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++){let px=x*T,py=y*T,n=tileNoise(x,y),floor=map.tiles[y][x],known=seen[y]?.[x];if(!known){rect(px,py,T,T,'#0b1218');continue;}if(floor){rect(px,py,T,T,n%3?b.floor:b.alt);if(run.floor<2){rect(px+(n%21),py+((n>>4)%24),3,2,'#596246');rect(px+((n>>6)%25),py+((n>>8)%25),2,5,'#4a583e');if(n%7===0){rect(px+8,py+18,11,4,'#504a39');rect(px+11,py+16,7,2,'#6a5a40');}if(n%11===0)rect(px+13,py+8,3,3,'#b69b51');}else{rect(px,py,T,1,'#171c2460');rect(px,py,1,T,'#151b2260');if(n%4===0)rect(px+5,py+8,10,1,'#80859122');if(n%9===0){rect(px+12,py+18,8,2,'#1b2228');rect(px+18,py+20,2,5,'#1b2228');}}}else{rect(px,py,T,T,b.wall);let below=map.tiles[y+1]?.[x];if(below){rect(px,py-6,T,T+7,'#151c23');rect(px,py-10,T,10,b.top);rect(px+1,py-9,T-2,2,'#a0a58b33');rect(px+1,py+2,14,12,b.wall);rect(px+17,py+2,14,12,b.wall);rect(px+5,py+17,22,9,b.wall);}else{rect(px,py,T,2,b.top);if(n%2===0)rect(px+4,py+9,20,2,'#ffffff06');}}}
 // Wall-side vegetation retains a legible central combat space.
 if(run.floor<2)for(let y=startY;y<endY;y++)for(let x=startX;x<endX;x++){let n=tileNoise(x,y);if(!map.tiles[y][x]&&seen[y]?.[x]&&n%7===0&&map.tiles[y+1]?.[x])tree(x*T+16,y*T+7,n,n%3===0);}}
function actor(o,player=false){let x=Math.round(o.x),y=Math.round(o.y),c=player?cls().color:o.type==='boss'?bio().bossColor:({rat:'#779751',bandit:'#a97b5b',archer:'#829367',skeleton:'#b5b6a2',mage:'#9383b5',knight:'#927f89',imp:'#bf6954'}[o.type]),sc=o.type==='boss'?2.2:1,walk=Math.sin(o.walk||0)*3,flash=o.flash>0||player&&o.invuln>0&&Math.sin(time*40)>0;ctx.save();ctx.translate(x,y);ctx.scale(sc,sc);ellipse(0,7,13,6,'#0006');if(player&&o.dashTime>0){ctx.globalAlpha=.6;rect(-12,-24,24,30,'#a6c4b05a');ctx.globalAlpha=1;}
 if(o.type==='rat'){ellipse(0,0,13,8,flash?'#f2ead6':c);rect(-8,-8,14,8,flash?'#f2ead6':'#91ab68');rect(o.angle>Math.PI/2||o.angle<-Math.PI/2?-11:7,-7,3,2,'#e8cd75');ctx.strokeStyle='#6e8454';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-10,3);ctx.lineTo(-18,8);ctx.lineTo(-21,5);ctx.stroke();rect(-7,7,3,3,'#384536');rect(6,7,3,3,'#384536');}
 else{rect(-7+walk*.4,1,5,10,'#2a292c');rect(3-walk*.4,1,5,10,'#2a292c');rect(-8+walk*.4,8,7,3,'#504339');rect(2-walk*.4,8,7,3,'#504339');rect(-10,-15,20,20,flash?'#fff2d6':c);rect(-10,-15,5,18,flash?'#fff2d6':'#00000030');rect(-6,-13,13,2,'#ffffff33');rect(-11,-1,22,4,'#3e3534');rect(-2,0,4,3,'#bc9b5b');rect(-6,-28,13,13,flash?'#fff2d6':o.type==='skeleton'?'#d0cbb4':'#c5a387');rect(-7,-29,15,5,flash?'#fff2d6':player?c:'#4c4343');rect(-7,-25,3,8,flash?'#fff2d6':c);rect(5,-25,3,8,flash?'#fff2d6':c);rect(-4,-22,3,2,'#25292b');rect(2,-22,3,2,'#25292b');rect(-3,-17,6,2,'#8d695c');rect(-14,-13,4,13,flash?'#fff2d6':c);rect(10,-13,4,13,flash?'#fff2d6':c);rect(-14,-2,4,4,'#c0a085');rect(10,-2,4,4,'#c0a085');
 let a=o.angle||0;ctx.save();ctx.translate(11,-7);ctx.rotate(a+Math.PI/2);if(player&&cls().kind==='arrow'||o.type==='archer'){ctx.strokeStyle='#be9d62';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-7,13,Math.PI*.2,Math.PI*.8);ctx.stroke();ctx.strokeStyle='#cabbaa';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-10,1);ctx.lineTo(10,1);ctx.stroke();}else if(player&&['fire','soul','spark'].includes(cls().kind)||o.type==='mage'){rect(-2,-24,4,32,'#8f7256');ellipse(0,-25,5,5,player?cls().color:'#c084cd');rect(-1,-28,2,5,'#e2e6ce');}else{rect(-2,-23,4,24,'#bdc7bc');rect(-1,-24,2,22,'#eef0d2');rect(-6,-1,12,3,'#b29957');rect(-2,2,4,7,'#66513d');}ctx.restore();
 if(o.type==='boss'){rect(-10,-33,20,5,'#d0ab65');rect(-11,-39,4,10,'#d0ab65');rect(-2,-41,4,12,'#e4c276');rect(7,-39,4,10,'#d0ab65');ellipse(0,-35,2,3,'#cd5e4a');}}
 ctx.restore();if(!player&&o.hp<o.max&&o.hp>0){rect(x-17*sc,y-37*sc,34*sc,4,'#10171c');rect(x-16*sc,y-37*sc,32*sc*o.hp/o.max,3,o.type==='boss'?'#d59b63':'#b85050');}if(player){let s=stats();rect(x-13,y-38,26,3,'#121c23');rect(x-13,y-38,26*p.hp/s.hp,3,'#bd5551');rect(x-13,y-34,26*p.mana/s.mana,2,'#64a5bf');}}
function object(o){let x=o.x,y=o.y;if(o.type==='torch'){rect(x-3,y-12,6,21,'#64533a');rect(x-5,y-19,10,8,'#d5a35d');ellipse(x,y-22,4+Math.sin(time*12+x)*1.5,8,'#efc47a');ellipse(x,y-23,2,4,'#fff2b4');}
 if(o.type==='barrel'){if(o.broken){rect(x-12,y+3,9,3,'#806344');rect(x+5,y+5,8,3,'#70573d');return;}ellipse(x,y+7,14,6,'#0005');rect(x-11,y-16,22,23,'#76583b');rect(x-9,y-18,18,4,'#ad8552');rect(x-11,y-12,22,3,'#494b45');rect(x-11,y+1,22,3,'#494b45');rect(x-4,y-13,2,14,'#c193573f');}
 if(o.type==='chest'){ellipse(x,y+9,18,7,'#0006');rect(x-15,y-8,30,18,o.open?'#413b32':'#93663c');rect(x-15,y-16,30,o.open?4:10,'#be9050');rect(x-15,y-8,30,3,'#423a30');rect(x-11,y-14,3,22,'#cba756');rect(x+8,y-14,3,22,'#cba756');rect(x-3,y-6,6,7,'#e8c777');if(o.open)rect(x-11,y-9,22,5,'#131b1d');}
 if(o.type==='bird'){rect(x-3,y-5,6,18,'#686353');rect(x-18,y-10,36,5,'#77725b');if(!o.used){ellipse(x,y-20,10,9,'#17242e');rect(x+6,y-29,7,12,'#1f303b');rect(x+12,y-26,7,3,'#ad9b65');rect(x+9,y-27,2,2,'#ffd785');ctx.fillStyle='#354d5b';ctx.beginPath();ctx.moveTo(x-7,y-21);ctx.lineTo(x-27,y-26+Math.sin(time*3)*5);ctx.lineTo(x-8,y-9);ctx.fill();}text(o.used?'Banked':'Courier',x,y+34,11,'#c4c8aa');}
 if(o.type==='shrine'){ellipse(x,y+9,20,8,'#0005');rect(x-17,y+1,34,10,'#6e7973');rect(x-10,y-19,20,23,'#919d8b');rect(x-6,y-28,12,15,o.used?'#555f5d':'#9ed8cb');if(!o.used){circleGlow(x,y-20,25,'#a3e1ca',.16);ellipse(x,y-21,3,6,'#e8ffda');}}
 if(o.type==='relic'){if(o.used)return;ellipse(x,y+7,17,7,'#0005');rect(x-11,y,22,8,'#626477');rect(x-5,y-13,10,15,'#9792a0');ctx.save();ctx.translate(x,y-25+Math.sin(time*2)*4);ctx.rotate(time*.6);rect(-6,-6,12,12,'#cbb77d');rect(-3,-3,6,6,'#ffe9ab');ctx.restore();circleGlow(x,y-24,32,'#eed39c',.12);}
 if(o.type==='exit'||o.type==='return'){let locked=o.locked,color=o.type==='return'?'#8ba8ae':locked?'#b56369':'#8cbcb1';ellipse(x,y+3,26,13,'#060d15');ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,y-4,23,32,0,0,TAU);ctx.stroke();for(let i=0;i<8;i++){let a=time+i*TAU/8;ellipse(x+Math.cos(a)*18,y-5+Math.sin(a)*25,2,3,color);}text(o.type==='return'?'Refuge':locked?'Sealed':'Descend',x,y+44,11,color);}
 if(o.type==='trap'){let active=Math.sin(time*2+o.phase)>.65;rect(x-18,y-13,36,28,'#1a2428');for(let i=0;i<3;i++)for(let j=0;j<2;j++){let xx=x-12+i*12,yy=y-7+j*12;ctx.fillStyle=active?'#d1c4b1':'#726a60';ctx.beginPath();ctx.moveTo(xx-3,yy+3);ctx.lineTo(xx,yy-(active?13:2));ctx.lineTo(xx+3,yy+3);ctx.fill();}if(!active&&Math.sin(time*2+o.phase)>.3)rect(x-18,y+12,36,2,'#d48463');}}
function circleGlow(x,y,r,color,alpha){ctx.save();ctx.globalAlpha=alpha;let g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);ctx.restore();}
function drawEffects(){for(let f of effects){let a=clamp(f.life/f.max,0,1);ctx.save();ctx.globalAlpha=a;if(f.type==='particle')rect(f.x,f.y,f.size,f.size,f.color);if(f.type==='ring'||f.type==='blast'){ctx.strokeStyle=f.color;ctx.lineWidth=f.type==='blast'?8:3;ctx.beginPath();ctx.arc(f.x,f.y,f.r*(1-a*.45),0,TAU);ctx.stroke();if(f.type==='blast'){ctx.globalAlpha=a*.3;ctx.fillStyle=f.color;ctx.fill();}}if(f.type==='slash'){ctx.strokeStyle=f.color;ctx.lineWidth=10*a;ctx.beginPath();ctx.arc(f.x,f.y,f.r*.8,f.angle-1.1+(1-a),f.angle+.7+(1-a));ctx.stroke();ctx.strokeStyle='#fff0ce';ctx.lineWidth=2;ctx.stroke();}if(['zone','hostileZone','meteor'].includes(f.type)){ctx.globalAlpha=.12;ctx.fillStyle=f.color;ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,TAU);ctx.fill();ctx.globalAlpha=f.type==='hostileZone'&&f.max-f.life<f.delay?.8:.4;ctx.strokeStyle=f.color;ctx.lineWidth=2;ctx.setLineDash([7,7]);ctx.stroke();ctx.setLineDash([]);if(f.type==='meteor'){ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(f.x-45*a,f.y-220*a);ctx.lineTo(f.x,f.y);ctx.lineWidth=12*(1-a);ctx.stroke();}else for(let i=0;i<5;i++){let an=time+i*TAU/5;rect(f.x+Math.cos(an)*f.r*.7,f.y+Math.sin(an)*f.r*.7,3,3,f.color);}}if(f.type==='bolt'){ctx.strokeStyle=f.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(f.x,f.y);for(let i=1;i<6;i++){let a=i/6;ctx.lineTo(f.x+(f.x2-f.x)*a+Math.sin(i*5+time*50)*9,f.y+(f.y2-f.y)*a);}ctx.lineTo(f.x2,f.y2);ctx.stroke();}ctx.restore();}}
function drawMini(){const scale=2.4,mw=map.w*scale,mh=map.h*scale,x=W-mw-24,y=H-mh-30;rect(x-8,y-8,mw+16,mh+16,'#090f17c9');ctx.strokeStyle='#73786577';ctx.strokeRect(x-8,y-8,mw+16,mh+16);for(let yy=0;yy<map.h;yy++)for(let xx=0;xx<map.w;xx++)if(seen[yy][xx]&&map.tiles[yy][xx])rect(x+xx*scale,y+yy*scale,scale,scale,'#72827180');for(let o of objects)if(seen[Math.floor(o.y/T)]?.[Math.floor(o.x/T)]&&['exit','bird','relic','shrine'].includes(o.type))rect(x+o.x/T*scale-2,y+o.y/T*scale-2,4,4,{exit:'#e5c080',bird:'#73cbd1',relic:'#bd96e5',shrine:'#a7c894'}[o.type]);ellipse(x+p.x/T*scale,y+p.y/T*scale,3,3,'#fff1c0');text('MAP · EXPLORED '+Math.round(discovered.filter(Boolean).length/12*100)+'%',x+mw/2,y+mh+26,10,'#a5ac99');}
function drawTown(){ctx.fillStyle='#182329';ctx.fillRect(0,0,W,H);for(let y=0;y<26;y++)for(let x=0;x<41;x++){let n=tileNoise(x,y);rect(x*T,y*T,T,T,n%3?'#303d35':'#344238');if(n%3===0)rect(x*T+8,y*T+16,3,5,'#566348');}for(let y=0;y<H;y+=32)rect(W/2-60,y,120,32,y%64?'#5b5140':'#554c3c');for(let x=0;x<W;x+=32)rect(x,H/2-35,32,90,x%64?'#5b5140':'#554c3c');for(let [x,y,col] of [[220,230,'#8a5d43'],[960,270,'#665c77'],[220,620,'#6e7661'],[950,630,'#70614e']]){ellipse(x,y+40,120,35,'#0004');rect(x-95,y-80,190,130,'#5c5547');rect(x-91,y-78,182,125,'#86775c');rect(x-100,y-88,200,22,col);for(let j=0;j<4;j++)rect(x-110+j*8,y-120-j*15,220-j*16,18,col);rect(x-25,y-30,50,77,'#282c2a');rect(x-70,y-35,28,28,'#e2b365');rect(x+44,y-35,28,28,'#e2b365');}for(let i=0;i<20;i++)tree((i*137)%W,(i*239)%H,i,i%4===0);circleGlow(W/2,H/2,250,'#e8b960',.17);for(let i=0;i<12;i++){let x=W/2+Math.sin(time*.2+i)*100,y=H/2+Math.cos(time*.25+i*3)*80;rect(x,y,2,2,'#e4bd6588');}}
function render(){ctx.clearRect(0,0,W,H);ctx.imageSmoothingEnabled=false;if(mode!=='run'||!p||!map){drawTown();return;}ctx.save();ctx.translate(-Math.floor(cam.x)+(Math.random()-.5)*shake,-Math.floor(cam.y)+(Math.random()-.5)*shake);ground();for(let o of objects)if(seen[Math.floor(o.y/T)]?.[Math.floor(o.x/T)]&&['trap','exit','return'].includes(o.type))object(o);
 for(let e of entities){if(!e.active||e.state!=='windup')continue;let a=e.aim||0;ctx.save();ctx.globalAlpha=.2+Math.sin(time*13)*.08;ctx.fillStyle='#f08065';ctx.strokeStyle='#ffc58d';ctx.lineWidth=2;if(e.type==='boss'){ctx.beginPath();ctx.arc(e.x,e.y,e.attackCount%3===0?120:70,0,TAU);ctx.fill();ctx.stroke();}else{ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.arc(e.x,e.y,['archer','mage','imp'].includes(e.type)?200:48,a-.32,a+.32);ctx.closePath();ctx.fill();ctx.stroke();}ctx.restore();}
 for(let l of loot)if(seen[Math.floor(l.y/T)]?.[Math.floor(l.x/T)]){let yy=l.y+Math.sin(time*3+l.bob)*2;ellipse(l.x,l.y+5,5,2,'#0005');if(l.type==='gold'){rect(l.x-3,yy-4,6,7,'#e3bc63');rect(l.x-2,yy-4,3,2,'#fff1a2');}else if(l.type==='health'){rect(l.x-4,yy-5,8,10,'#c56c5d');rect(l.x-2,yy-8,4,4,'#a79573');}else{rect(l.x-5,yy-4,10,8,{wood:'#ae8554',stone:'#9a9e98',iron:'#b8abc0'}[l.type]);rect(l.x-3,yy-6,6,3,'#d4c59a');}}
 let drawables=[...objects.filter(o=>!['trap','exit','return'].includes(o.type)&&seen[Math.floor(o.y/T)]?.[Math.floor(o.x/T)]),...entities.filter(e=>e.hp>0&&seen[Math.floor(e.y/T)]?.[Math.floor(e.x/T)]),{...p,player:true}].sort((a,b)=>a.y-b.y);for(let o of drawables){if(o.player)actor(o,true);else if(o.max)actor(o);else object(o);}
 for(let b of shots){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.vy,b.vx));if(['arrow','knife','thorn'].includes(b.kind)){rect(-10,-1,18,2,b.enemy?'#e79d72':'#dec798');rect(7,-3,4,6,'#d8dbbc');}else{let color=b.enemy?'#e97a69':({fire:'#efb369',soul:'#89d0a7',spark:'#a2dfef',hammer:'#eee0a4'}[b.kind]||'#b8a9df');ellipse(0,0,b.r+2,b.r,color);ellipse(0,0,b.r*.4,b.r*.4,'#ffefd5');}ctx.restore();}
 drawEffects();for(let f of floaters){ctx.save();ctx.globalAlpha=f.life;text(f.text,f.x,f.y,14,f.color);ctx.restore();}
 // Soft torch pools and edge vignette leave telegraphs visible.
 ctx.globalCompositeOperation='screen';for(let o of objects)if(o.type==='torch'&&Math.abs(o.x-p.x)<700&&Math.abs(o.y-p.y)<500)circleGlow(o.x,o.y-20,100,bio().light,.1);circleGlow(p.x,p.y,150,'#b7c8a8',.045);ctx.globalCompositeOperation='source-over';
 let near=objects.filter(o=>!['torch','trap','barrel'].includes(o.type)&&!o.open&&!o.used&&dist(o,p)<64).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(near){let labels={chest:'Open chest',bird:'Bank half your haul',shrine:'Restore health & mana',relic:'Choose a trinket',exit:near.locked?'Defeat the guardian':'Descend',return:'Return to town'};text('[F] '+labels[near.type],near.x,near.y-48,13,'#ffe2a3');}
 ctx.restore();let g=ctx.createRadialGradient(W/2,H/2,180,W/2,H/2,750);g.addColorStop(0,'transparent');g.addColorStop(1,'#030811aa');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);drawMini();let boss=entities.find(e=>e.type==='boss'&&e.active&&e.hp>0);if(boss){let bw=420;rect(W/2-bw/2,H-59,bw,12,'#13191f');rect(W/2-bw/2+2,H-57,(bw-4)*boss.hp/boss.max,8,'#b66756');ctx.strokeStyle='#c7a772';ctx.strokeRect(W/2-bw/2,H-59,bw,12);text(bio().boss,W/2,H-69,16,'#ecd2aa');}if(paused){rect(0,0,W,H,'#0006');text('PAUSED',W/2,H/2,32,'#eace9b');}}
function guide(){const wasTown=mode==='town',wasPending=pendingResume;showPanel(`<div class="row"><div><div class="eyebrow">Field guide</div><h2>The road to the crown</h2></div><button id="guideBack">Close</button></div><div class="two"><div><h3>Explore, fight, return</h3><p>Six generated floors span Pinewild, Sunken Vaults and Ember Citadel. Guardians block floors 2, 4 and 6. Explore the branches for equipment, restoration shrines and three-choice trinkets. Defeat the Hollow King to begin New Game +.</p><h3>What survives?</h3><p>Character level, equipment, town construction and banked resources persist. Trinkets are temporary. A courier sends half your carried resources safely home. Death or retreat keeps 60% of what remains, increased by town upgrades. Victory keeps everything.</p><h3>Read the fight</h3><p>Orange cones and circles warn of enemy attacks. Dodge through danger; you are invulnerable during the dash. Mana regenerates. Potions restore both health and mana. Keyboard-only J attacks with nearby-target aim.</p></div><div><h3>Controls</h3><p>WASD / arrows: move<br>Mouse: aim · hold left click: attack<br>J: attack with nearby-target aim (when mouse inactive)<br>Space: dodge · Q / E: class skills<br>F: interact · R: potion<br>Tab: equipment · Escape: pause<br>Touch: movement pad and action buttons; automatic aim</p><h3>About this interpretation</h3><p>This is an original, solo browser game informed by the <a href="https://wiki.heroesofhammerwatch2.com/Main_Page" target="_blank" rel="noopener">Heroes of Hammerwatch II wiki</a> and <a href="https://store.steampowered.com/app/619820/Heroes_of_Hammerwatch_II/" target="_blank" rel="noopener">official Steam listing</a>. It does not contain the original game’s code, art, music or maps.</p><p class="muted">Compared with the commercial game: three original environments and guardians rather than eight environments/six acts; simplified class specializations and town; no co-op, quest NPC rescues, full skill trees, crafting/enchanting or DLC. It is a smaller interpretation, not a feature-identical port.</p></div></div>`);bind('guideBack',()=>wasPending?welcomePanel():wasTown?townPanel():closePanel());}
function pauseMenu(){if(mode!=='run')return;if(panel){closePanel();return;}showPanel(`<div class="eyebrow">Take a breath</div><h2>Expedition paused</h2><p>Your progress saves automatically on this device. You can close this tab and resume your expedition later.</p><div class="row wrap"><button class="primary" id="continue">Resume</button><button id="armory">Equipment</button><button id="controls">Controls</button><button id="abandon">Retreat to town</button></div>`,true);bind('continue',closePanel);bind('armory',()=>inventoryPanel());bind('controls',guide);bind('abandon',()=>{showPanel(`<h2>Retreat to town?</h2><p>Keep all equipment and experience, and ${Math.round(Math.min(.85,.6+.05*save.buildings.chapel+.025*save.buildings.treasury)*100)}% of carried resources.</p><div class="row"><button id="cancel">Stay</button><button id="confirmRetreat">Retreat</button></div>`,true);bind('cancel',pauseMenu);bind('confirmRetreat',()=>finishRun(false,true));});persist();}
window.addEventListener('keydown',e=>{let key=e.key.length===1?e.key.toLowerCase():e.key;if([' ','Tab','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key))e.preventDefault();if(e.repeat&&['f','r','Escape','Tab'].includes(key))return;if(key==='Escape'){pauseMenu();return;}if(mode!=='run'||panel)return;keys[key]=true;if(key==='f')interact();if(key==='r')potion();if(key==='Tab')inventoryPanel();if(key==='j')mouse.active=false;});window.addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false;});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;let r=canvas.getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H),ox=(r.width-W*scale)/2,oy=(r.height-H*scale)/2;mouse.x=(e.clientX-r.left-ox)/scale;mouse.y=(e.clientY-r.top-oy)/scale;mouse.active=true;});canvas.addEventListener('pointerdown',e=>{if(e.button!==0||panel)return;mouse.down=true;canvas.focus();if(e.pointerType==='touch')mouse.active=false;});window.addEventListener('pointerup',()=>mouse.down=false);window.addEventListener('blur',()=>{clearInput();if(mode==='run'&&!panel){paused=true;persist();}});window.addEventListener('focus',()=>{paused=false;last=performance.now();});document.addEventListener('visibilitychange',()=>{clearInput();if(document.hidden)persist();last=performance.now();});window.addEventListener('beforeunload',persist);canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();let k=b.dataset.key;if(mode!=='run'||panel)return;mouse.active=false;keys[k]=true;if(k==='f')interact();if(k==='r')potion();b.setPointerCapture(e.pointerId);});const up=e=>{e.preventDefault();keys[b.dataset.key]=false;};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);});
bind('sound',()=>{save.settings.sound=!save.settings.sound;$('#sound').textContent=save.settings.sound?'Sound on':'Sound off';sound('coin');persist();});$('#sound').textContent=save.settings.sound?'Sound on':'Sound off';bind('help',guide);bind('journal',guide);bind('pause',pauseMenu);
function frame(now){let dt=Math.min(.035,(now-last)/1000||.016);last=now;try{update(dt);render();}catch(err){console.error(err);paused=true;notify('An unexpected error paused the game. Reload to restore the latest save.');}requestAnimationFrame(frame);}
function welcomePanel(){showPanel(`<div class="eyebrow">Welcome back</div><h1>YOUR EXPEDITION AWAITS</h1><p>${CLASSES.find(c=>c.id===save.classId)?.name||'Hero'} · Depth ${save.run.floor+1} · ${save.run.kills} defeated</p><div class="row"><button class="primary" id="resumeRun">Resume expedition</button><button id="retreatSaved">Retreat to town</button></div>`,true);bind('resumeRun',resumeRun);bind('retreatSaved',()=>{resumeRun();finishRun(false,true);});}
if(save.run)welcomePanel();else townPanel();requestAnimationFrame(frame);
// Optional, read-only WebMCP status. This never plays or changes game state.
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_emberwatch_progress',title:'Read Emberwatch progress',description:'Read the same hero, expedition and town progress shown in the game interface. No game actions are taken.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {hero:cls().name,level:hero().level,mode,depth:run?run.floor+1:null,health:p?Math.ceil(p.hp):null,carried:run?{gold:run.gold,wood:run.wood,stone:run.stone,iron:run.iron}:null,town:{gold:save.gold,wood:save.wood,stone:save.stone,iron:save.iron},victories:save.wins};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
